import google.generativeai as genai
import os

def check_unsafe_content(text: str) -> dict:
    """
    Checks the given text for unsafe content using Google's Generative AI.

    Args:
        text: The message payload text to check.

    Returns:
        A dictionary containing the safety ratings from the API.
    """
    # Configure the API key. In a real application, this should be handled securely,
    # e.g., via environment variables or a secret management service.
    # For this example, we assume GOOGLE_API_KEY is set in the environment.
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))

    model = genai.GenerativeModel('gemini-pro')

    response = model.generate_content(
        text,
        safety_settings=[
            {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
        ]
    )

    # The safety_ratings are available in the prompt_feedback.
    # If content was blocked, response.prompt_feedback would contain the reasons.
    # If the response is empty (e.g., due to content being blocked before generation),
    # then safety_ratings might be in response.prompt_feedback.
    if hasattr(response, 'prompt_feedback') and response.prompt_feedback.safety_ratings:
        return {
            "is_safe": not any(
                rating.blocked for rating in response.prompt_feedback.safety_ratings
            ),
            "safety_ratings": [
                {"category": rating.category.name, "probability": rating.probability.name}
                for rating in response.prompt_feedback.safety_ratings
            ],
        }
    elif response.candidates:
        # If there are candidates, check their safety ratings
        for candidate in response.candidates:
            if hasattr(candidate, 'safety_ratings') and candidate.safety_ratings:
                return {
                    "is_safe": not any(
                        rating.blocked for rating in candidate.safety_ratings
                    ),
                    "safety_ratings": [
                        {"category": rating.category.name, "probability": rating.probability.name}
                        for rating in candidate.safety_ratings
                    ],
                }
    return {"is_safe": True, "safety_ratings": []}

import json
from typing import Dict, Any, Optional

class PubsubMessage:
    """Represents a message for Pub/Sub, either for publishing or consuming."""
    def __init__(self, data: bytes, attributes: Optional[Dict[str, str]] = None, message_id: Optional[str] = None):
        if not isinstance(data, bytes):
            raise TypeError("Message data must be bytes.")
        self.data: bytes = data
        self.attributes: Dict[str, str] = attributes if attributes is not None else {}
        self.message_id: Optional[str] = message_id

    def to_json_data(self) -> Dict[str, Any]:
        """Decodes message data from bytes to a JSON dictionary."""
        try:
            return json.loads(self.data.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise ValueError(f"Could not decode message data as JSON: {e}") from e

    @classmethod
    def from_json_data(cls, json_data: Dict[str, Any], attributes: Optional[Dict[str, str]] = None) -> 'PubsubMessage':
        """Creates a PubsubMessage from a JSON dictionary."""
        data_bytes = json.dumps(json_data).encode('utf-8')
        return cls(data=data_bytes, attributes=attributes)

class PublishResponse:
    """Represents the response from a Pub/Sub publish operation."""
    def __init__(self, message_id: str):
        self.message_id: str = message_id

def normalize_attributes(attributes: Optional[Dict[str, Any]]) -> Dict[str, str]:
    """Ensures attributes are a dictionary of string keys and string values."""
    if attributes is None:
        return {}
    normalized = {}
    for key, value in attributes.items():
        if not isinstance(key, str):
            key = str(key)
        if not isinstance(value, str):
            value = str(value)
        normalized[key] = value
    return normalized

from google.cloud import pubsub_v1
import os

class PubSubClient:
    def __init__(self, project_id=None):
        if project_id is None:
            self.project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
            if not self.project_id:
                raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")
        else:
            self.project_id = project_id

        self.publisher = pubsub_v1.PublisherClient()
        self.subscriber = pubsub_v1.SubscriberClient()

    def get_publisher_client(self):
        return self.publisher

    def get_subscriber_client(self):
        return self.subscriber

    def topic_path(self, topic_id):
        return self.publisher.topic_path(self.project_id, topic_id)

    def subscription_path(self, subscription_id):
        return self.subscriber.subscription_path(self.project_id, subscription_id)
